"""Integration tests on a small synthetic video generated by FFmpeg."""

import json
import shutil
import subprocess

import pytest

from probing_qc.qc import QCConfig, run_qc
from probing_qc.qc.frames import FrameSampler
from probing_qc.qc.metadata import probe_video

pytestmark = pytest.mark.skipif(shutil.which("ffmpeg") is None, reason="FFmpeg not installed")


@pytest.fixture(scope="module")
def video(tmp_path_factory):
    path = tmp_path_factory.mktemp("qc") / "test.mp4"
    subprocess.run(["ffmpeg", "-v", "error", "-f", "lavfi", "-i", "testsrc2=size=320x240:rate=30:duration=2",
                    "-c:v", "libx264", "-pix_fmt", "yuv420p", str(path)], check=True)
    return path


def test_probe(video):
    info = probe_video(video)
    assert (info.width, info.height, info.codec) == (320, 240, "h264")
    assert info.fps == pytest.approx(30) and info.frame_count == 60
    assert not info.has_gpmf


def test_sampler_takes_every_nth_frame(video):
    sampler = FrameSampler(probe_video(video), stride=4)
    frames = list(sampler)
    assert [f.index for f in frames] == list(range(0, 60, 4))
    assert frames[1].timestamp_s == pytest.approx(4 / 30)
    assert frames[0].rgb.shape == (240, 320, 3)
    assert sampler.errors == [] and sampler.returncode == 0
    assert sampler.expected_frames == len(frames)


def test_sampler_early_stop_cleans_up(video):
    sampler = FrameSampler(probe_video(video), stride=1)
    for _ in zip(range(3), sampler):
        pass
    assert sampler.returncode is not None  # ffmpeg was reaped


def test_run_qc_report_shape(video):
    cfg = QCConfig.from_dict({"hands": {"enabled": False}})
    result = run_qc(video, cfg, progress=False)
    r = result.report
    json.dumps(r)  # must be serialisable
    assert r["sampling"]["frames_analyzed"] == 15 == len(result.frames)
    tech = r["technical"]
    for key in ("duration", "fps", "bitrate", "codec", "luminance", "sharpness",
                "blockiness", "colour_cast", "decode_errors", "orientation"):
        assert key in tech, key
    assert tech["decode_errors"]["count"] == 0
    assert tech["orientation"]["display"] == "landscape"
    assert "hands" not in r
